actions.script:
hasValidCache = false
if (bufferList) {
    def cachedRow = bufferList[0]
    ec.logger.info("cachedRow: " + cachedRow)
    if (cachedRow.metaJsonBuffer != null && !cachedRow.metaJsonBuffer.contains('"error"')) {
        hasValidCache = true
        metaJsonBuffer = cachedRow.metaJsonBuffer
        workspaceBufferId = cachedRow.workspaceBufferId
    } else {
        // Safely clear out the poison pill via inline execution facade context
        ec.service.sync().name("delete#org.moqui.ai.WorkspaceBuffer")
            .parameter("workspaceBufferId", cachedRow.workspaceBufferId).call()
    }
}

else.script:
if (rawJsonText) {
    // Stitch missing sibling object commas: \}\s*\{ -> },{
    rawJsonText = rawJsonText.trim().replaceAll("\\}\\s*\\{", "},{");

    // Map json-ld "@type" tokens to standard flat "type" keys
    rawJsonText = rawJsonText.replaceAll("\"@type\"", "\"type\"");
} else {
    rawJsonText = "{ \"id\": \"root\", \"tagName\": \"form\", \"children\": [] }";
}

// Explicit boolean marker calculation isolated from XML parsing constraints
shouldSaveToDb = !rawJsonText.contains('"error"')

actions.script:
def buildXmlNode(Map nodeMap) {
    String tagName = nodeMap.tagName ?: "container"
    StringBuilder sb = new StringBuilder("<${tagName}")

    // Inject properties as valid XML attributes
    nodeMap.each { k, v ->
        if (k != 'children' && k != 'tagName' && k != 'id' && v != null) {
            sb.append(" ${k}=\"${v}\"")
        }
    }

    if (nodeMap.children) {
        sb.append(">\n")
        nodeMap.children.each { child ->
            sb.append(buildXmlNode(child as Map))
        }
        sb.append("</${tagName}>\n")
    } else {
        sb.append("/>\n")
    }
    return sb.toString()
}

// Wrap your dynamic layout elements in the standard screen envelope structure
String rawTreeText = buildXmlNode(layoutTree)
xmlText = """<?xml version="1.0" encoding="UTF-8"?>
           <screen xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
               <widgets>
                   ${rawTreeText}
               </widgets>
           </screen>"""
